import time
import math


class KVCache:
    def __init__(self, capacity, ttl_seconds, clock=None):
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise ValueError("capacity must be a non-bool integer")
        if capacity < 0:
            raise ValueError("capacity must be >= 0")
        if isinstance(ttl_seconds, bool):
            raise ValueError("ttl_seconds must be a non-bool number")
        if not isinstance(ttl_seconds, (int, float)):
            raise ValueError("ttl_seconds must be a finite number")
        if isinstance(ttl_seconds, float) and not math.isfinite(ttl_seconds):
            raise ValueError("ttl_seconds must be finite")
        if ttl_seconds < 0:
            raise ValueError("ttl_seconds must be >= 0")

        self.capacity = capacity
        self.ttl_seconds = ttl_seconds
        self.clock = clock if clock is not None else time.monotonic
        # key -> [value, expiry]
        self._store = {}
        # key -> node in doubly linked list (LRU order; head = MRU, tail = LRU)
        self._head = None
        self._tail = None
        self._nodes = {}

    def _now(self):
        return self.clock()

    def _unlink(self, key):
        node = self._nodes.pop(key, None)
        if node is None:
            return
        prev, nxt = node[0], node[2]
        if prev is not None:
            prev[2] = nxt
        else:
            self._head = nxt
        if nxt is not None:
            nxt[0] = prev
        else:
            self._tail = prev
        node[0] = node[2] = None

    def _link_front(self, key):
        node = [None, key, None]  # [prev, key, next]
        node[2] = self._head
        if self._head is not None:
            self._head[0] = node
        self._head = node
        if self._tail is None:
            self._tail = node
        self._nodes[key] = node

    def _touch(self, key):
        self._unlink(key)
        self._link_front(key)

    def _is_expired(self, key, now):
        entry = self._store.get(key)
        if entry is None:
            return False
        return now >= entry[1]

    def _purge_expired(self):
        now = self._now()
        expired = [k for k, entry in self._store.items() if now >= entry[1]]
        for k in expired:
            self._store.pop(k, None)
            self._unlink(k)

    def get(self, key):
        now = self._now()
        entry = self._store.get(key)
        if entry is None:
            return None
        if now >= entry[1]:
            # expired: treat as missing
            self._store.pop(key, None)
            self._unlink(key)
            return None
        self._touch(key)
        return entry[0]

    def put(self, key, value):
        now = self._now()
        expiry = now + self.ttl_seconds
        entry = self._store.get(key)
        if entry is not None:
            # updating existing key: refresh TTL and mark MRU
            entry[0] = value
            entry[1] = expiry
            self._touch(key)
            return
        # inserting new key: make room if needed
        if self.capacity == 0:
            return
        if self.ttl_seconds == 0:
            return
        if len(self._store) >= self.capacity:
            self._purge_expired()
            if len(self._store) >= self.capacity:
                # evict LRU live entry
                lru_key = self._tail[1]
                self._store.pop(lru_key, None)
                self._unlink(lru_key)
        self._store[key] = [value, expiry]
        self._link_front(key)

    def delete(self, key):
        entry = self._store.get(key)
        if entry is None:
            return False
        now = self._now()
        if now >= entry[1]:
            # expired entry: deleting counts as failure
            self._store.pop(key, None)
            self._unlink(key)
            return False
        self._store.pop(key, None)
        self._unlink(key)
        return True
